-- #快捷入口

-- #系统菜单
COMMIT;
-- #系统权限
SET SESSION group_concat_max_len = 1000000;
SET @super_menu_ids = (SELECT COALESCE(CONCAT('[', GROUP_CONCAT(JSON_QUOTE(CAST(`id` AS CHAR)) ORDER BY `id` SEPARATOR ','), ']'), '[]') FROM `eb_system_menus` WHERE `deleted_at` IS NULL AND `type` = 'M');
SET @super_menu_unique = (SELECT COALESCE(CONCAT('[', GROUP_CONCAT(JSON_QUOTE(`unique_auth`) ORDER BY `id` SEPARATOR ','), ']'), '[]') FROM `eb_system_menus` WHERE `deleted_at` IS NULL AND `type` = 'M');
SET @super_api_ids = (SELECT COALESCE(CONCAT('[', GROUP_CONCAT(JSON_QUOTE(CAST(`id` AS CHAR)) ORDER BY `id` SEPARATOR ','), ']'), '[]') FROM `eb_system_menus` WHERE `deleted_at` IS NULL AND `type` IN ('B', 'A'));
SET @super_api_unique = (SELECT COALESCE(CONCAT('[', GROUP_CONCAT(JSON_QUOTE(`unique_auth`) ORDER BY `id` SEPARATOR ','), ']'), '[]') FROM `eb_system_menus` WHERE `deleted_at` IS NULL AND `type` IN ('B', 'A'));
UPDATE `eb_system_role`
SET `rules` = @super_menu_ids, `apis` = @super_api_ids
WHERE `id` = 1;
UPDATE `eb_enterprise_role`
SET `data_level` = 5,
    `directly` = 1,
    `frame_id` = '[]',
    `module_permissions` = '{"customer":{"data_level":5,"frame_id":[],"directly":1},"attendance":{"data_level":5,"frame_id":[],"directly":1},"assess":{"data_level":5,"frame_id":[],"directly":1},"schedule":{"data_level":5,"frame_id":[],"directly":1},"report":{"data_level":5,"frame_id":[],"directly":1},"program":{"data_level":5,"frame_id":[],"directly":1}}',
    `rules` = @super_menu_ids,
    `rule_unique` = @super_menu_unique,
    `apis` = @super_api_ids,
    `api_unique` = @super_api_unique
WHERE `id` = 1;
